<?php
declare(strict_types=1);
session_start();
require dirname(__DIR__,2).'/config/config.php';
function hr_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())hr_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))hr_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(($_SESSION['role']??'')!=='hr')hr_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for HR accounts.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)hr_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())hr_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$roles="'director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";$q=$db->prepare("SELECT COUNT(DISTINCT u.id) FROM school_memberships m JOIN users u ON u.id=m.user_id WHERE m.school_id=? AND u.status='active' AND u.role IN ($roles)");$q->execute([$school]);$staff=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM staff_leave_requests WHERE school_id=? AND status='pending'");$q->execute([$school]);$pending=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM employee_contracts WHERE school_id=? AND status='active' AND end_date BETWEEN CURRENT_DATE AND DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY)");$q->execute([$school]);$expiring=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) FROM employee_contracts WHERE school_id=? AND status='active' AND end_date<CURRENT_DATE");$q->execute([$school]);$ended=(int)$q->fetchColumn();$q=$db->prepare("SELECT c.id,c.user_id,c.start_date,c.end_date,u.name staff_name,u.role,DATEDIFF(c.end_date,CURRENT_DATE) days_until_expiry FROM employee_contracts c JOIN users u ON u.id=c.user_id WHERE c.school_id=? AND c.status='active' AND c.end_date<=DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY) AND u.role NOT IN ('system_admin','sub_admin','admin','parent') ORDER BY c.end_date,c.id LIMIT 20");$q->execute([$school]);$contractAlerts=$q->fetchAll();$q=$db->prepare("SELECT l.id,l.leave_type,l.start_date,l.end_date,l.status,l.created_at,u.name staff_name,u.role FROM staff_leave_requests l JOIN users u ON u.id=l.user_id JOIN school_memberships m ON m.school_id=l.school_id AND m.user_id=u.id WHERE l.school_id=? ORDER BY (l.status='pending') DESC,l.created_at DESC,l.id DESC LIMIT 10");$q->execute([$school]);hr_dashboard_json(200,['ok'=>true,'data'=>['active_staff'=>$staff,'pending_leave'=>$pending,'contracts_expiring'=>$expiring,'contracts_ended'=>$ended,'contract_alerts'=>$contractAlerts,'recent_leave'=>$q->fetchAll()]]);}catch(Throwable $e){error_log('HR dashboard request failed: '.$e->getMessage());hr_dashboard_json(500,['ok'=>false,'message'=>'HR dashboard data could not be loaded.']);}
